            ,1'b0
            ,1'b0
            ,1'b0
            ,1'b0
            ,1'b0
            ,1'b0
            ,1'b0
            ,bjp_req_alu_cmp_eq
            ,bjp_req_alu_cmp_ne
            ,bjp_req_alu_cmp_lt
            ,bjp_req_alu_cmp_gt
            ,bjp_req_alu_cmp_ltu
            ,bjp_req_alu_cmp_gtu

        })
      | ({DPATH_MUX_WIDTH{agu_req_alu}} & {
             agu_req_alu_op1
            ,agu_req_alu_op2
            ,agu_req_alu_max
            ,agu_req_alu_min
            ,agu_req_alu_maxu
            ,agu_req_alu_minu
            ,agu_req_alu_add
            ,1'b0
            ,agu_req_alu_or
            ,agu_req_alu_xor
            ,agu_req_alu_and
            ,1'b0
            ,1'b0
            ,1'b0
            ,1'b0
            ,1'b0
            ,agu_req_alu_swap
            ,1'b0
            ,1'b0
            ,1'b0
            ,1'b0
            ,1'b0
            ,1'b0
        })
        ;

  assign alu_req_alu_res     = alu_dpath_res[`E203_XLEN-1:0];
  assign agu_req_alu_res     = alu_dpath_res[`E203_XLEN-1:0];
  assign bjp_req_alu_add_res = alu_dpath_res[`E203_XLEN-1:0];
  assign bjp_req_alu_cmp_res = cmp_res;
`ifdef E203_SUPPORT_SHARE_MULDIV
  assign muldiv_req_alu_res  = adder_res;
`endif

  assign sbf_0_ena =
`ifdef E203_SUPPORT_SHARE_MULDIV
      muldiv_req_alu ? muldiv_sbf_0_ena :
`endif
                 agu_sbf_0_ena;
  assign sbf_1_ena =
`ifdef E203_SUPPORT_SHARE_MULDIV
      muldiv_req_alu ? muldiv_sbf_1_ena :
`endif
                 agu_sbf_1_ena;

  assign sbf_0_nxt =
`ifdef E203_SUPPORT_SHARE_MULDIV
      muldiv_req_alu ? muldiv_sbf_0_nxt :
`endif
                 {1'b0,agu_sbf_0_nxt};
  assign sbf_1_nxt =
`ifdef E203_SUPPORT_SHARE_MULDIV
      muldiv_req_alu ? muldiv_sbf_1_nxt :
`endif
                 {1'b0,agu_sbf_1_nxt};

  assign agu_sbf_0_r = sbf_0_r[`E203_XLEN-1:0];
  assign agu_sbf_1_r = sbf_1_r[`E203_XLEN-1:0];

`ifdef E203_SUPPORT_SHARE_MULDIV
  assign muldiv_sbf_0_r = sbf_0_r;
  assign muldiv_sbf_1_r = sbf_1_r;
`endif

endmodule

