                  status_mie_r;

sirv_gnrl_dfflr #(1) status_mie_dfflr (status_mie_ena, status_mie_nxt, status_mie_r, clk, rst_n);








wire [1:0] status_fs_r;
wire [1:0] status_xs_r;
