module sd_crc_16(BITVAL, Enable, CLK, RST, CRC);
 input        BITVAL;// Next input bit
   input Enable;
   input        CLK;                           // Current bit valid (Clock)
   input        RST;                             // Init CRC value
   output reg [15:0] CRC;                               // Current output CRC value


                     // We need output registers
   wire         inv;

   assign inv = BITVAL ^ CRC[15];                   // XOR required?

  always @(posedge CLK or posedge RST) begin
		if (RST) begin
			CRC <= 0;   

        end
      else begin
        if (Enable==1) begin
         CRC[15] <= CRC[14];
         CRC[14] <= CRC[13];
         CRC[13] <= CRC[12];
         CRC[12] <= CRC[11] ^ inv;
         CRC[11] <= CRC[10];
         CRC[10] <= CRC[9];
         CRC[9] <= CRC[8];
         CRC[8] <= CRC[7];
         CRC[7] <= CRC[6];
         CRC[6] <= CRC[5];
         CRC[5] <= CRC[4] ^ inv;
         CRC[4] <= CRC[3];
         CRC[3] <= CRC[2];
         CRC[2] <= CRC[1];
         CRC[1] <= CRC[0];
         CRC[0] <= inv;
        end
         end
      end

   cover property (@(posedge CLK) Enable && !RST |=> 
         (CRC[15] == CRC[14]) &&
         (CRC[14] == CRC[13]) &&
         (CRC[13] == CRC[12]) &&
         (CRC[12] == (CRC[11] ^ inv)) &&
         (CRC[11] == CRC[10]) &&
         (CRC[10] == CRC[9]) &&
         (CRC[9] == CRC[8]) &&
         (CRC[8] == CRC[7]) &&
         (CRC[7] == CRC[6]) &&
         (CRC[6] == CRC[5]) &&
         (CRC[5] == CRC[4] ^ inv) &&
         (CRC[4] == CRC[3]) &&
         (CRC[3] == CRC[2]) &&
         (CRC[2] == CRC[1]) &&
         (CRC[1] == CRC[0]) &&
         (CRC[0] == inv));    //enable
   cover property (@(posedge CLK) RST |=> CRC==16'b0000000000000000); //reset 
   cover property (@(negedge CLK) CRC == CRC);

endmodule

