    input          m_wb_ack_i,
    output  reg    [2:0] m_wb_cti_o,
    output  reg    [1:0] m_wb_bte_o,

    //Data Master Control signals
    input en,
    input [31:0] adr,

    //Data Serial signals 
    input sd_clk,
    output [31:0] dat_o,
    input rd,
    output empty,
    output fe
);

