cover property (@(posedge clk) wr_tx |-> !fe);  // 写入时FIFO非满状态
cover property (@(posedge clk) !empty |-> rd);  // 非空时读取
cover property (@(posedge clk) en |-> !reset_tx_fifo);  // 使能时FIFO不复位


